import { readFile, writeFile } from "node:fs/promises";
import { basename, join, resolve } from "node:path";
import { buildTeamsAppPackage, DEFAULT_TEAMS_APP_ENGAGEMENT, teamsAppManifest, teamsAppPackageFileName, teamsAppPackageVersion, } from "../teams-app-package.js";
import { CliError } from "./cli/errors.js";
import { CLI_COMMAND_NAME as CLI } from "./distribution.js";
import { describeError } from "./describe-error.js";
import { ensureGitignoreEntry } from "./env-file.js";
import { isGuid } from "./guid.js";
import { loadAgentLocalEnv } from "./local-env.js";
import { credentialsInCodeMessage, loadTeamsChannelProfile, } from "./teams-channel-profile.js";
const TEAMS_APP_ZIP_GITIGNORE = "*-teams-app.zip";
const UPLOAD_LINE = "Upload it in Teams: Apps, Manage your apps, Upload an app.";
export async function cmdTeamsPackage(options) {
    const out = options.out ?? ((text) => void process.stdout.write(text));
    const dir = resolve(options.dir);
    const profile = await loadTeamsChannelProfile({
        dir: options.dir,
        slug: options.slug,
        channel: options.channel,
    });
    loadAgentLocalEnv(dir);
    const notes = [];
    if (options.dryRun === true) {
        notes.push("Dry run. Nothing written.");
    }
    const appId = readAppId(profile);
    const engagement = engagementFor(profile, notes);
    const packageSlug = profile.slug !== "" ? profile.slug : basename(dir);
    const input = {
        appId,
        name: options.name ?? packageSlug,
        version: options.appVersion ?? teamsAppPackageVersion(options.now ?? new Date()),
        engagement,
        messagingEndpoints: options.endpoint === undefined ? [] : [options.endpoint],
        colorIcon: options.icon === undefined ? undefined : await readColorIcon(options.icon),
    };
    let manifest;
    let zip;
    try {
        manifest = teamsAppManifest(input);
        zip = buildTeamsAppPackage(input, manifest);
    }
    catch (error) {
        throw invalidArgumentOrRethrow(error);
    }
    const zipPath = options.outPath === undefined
        ? join(dir, teamsAppPackageFileName(packageSlug))
        : resolve(options.outPath);
    if (options.dryRun !== true) {
        await writeFile(zipPath, zip);
        if (options.outPath === undefined) {
            await ensureGitignoreEntry(dir, TEAMS_APP_ZIP_GITIGNORE);
        }
    }
    const report = {
        ok: true,
        path: zipPath,
        appId,
        version: manifest.version,
        scopes: manifest.bots[0].scopes,
        channelPosts: engagement.channelPosts,
        notes,
    };
    out(options.json === true
        ? `${JSON.stringify(report, null, 2)}\n`
        : renderReport(report, options.dryRun === true));
    return 0;
}
function engagementFor(profile, notes) {
    if (profile.engagement !== undefined) {
        return profile.engagement;
    }
    notes.push("The channel does not declare which chats it answers. The app allows personal chats and @mentions.");
    return DEFAULT_TEAMS_APP_ENGAGEMENT;
}
function readAppId(profile) {
    if (profile.credentialEnv === undefined) {
        throw new CliError(`${credentialsInCodeMessage(profile)}, and package needs the app id.`, {
            code: "failed_precondition",
            hint: "Read the credentials from env (teamsChannel() or teamsChannel({ envPrefix })) to build the package.",
        });
    }
    const keys = profile.credentialEnv.keys;
    const value = process.env[keys.appId]?.trim() ?? "";
    if (value === "") {
        throw new CliError(`${keys.appId} is missing. Run \`${CLI} channels teams init\`.`, {
            code: "failed_precondition",
        });
    }
    if (!isGuid(value)) {
        throw new CliError(`${keys.appId} must be a GUID such as 00000000-0000-0000-0000-000000000000.`, { code: "invalid_argument" });
    }
    return value;
}
function invalidArgumentOrRethrow(error) {
    if (!(error instanceof Error)) {
        throw error;
    }
    return new CliError(error.message, { code: "invalid_argument", cause: error });
}
async function readColorIcon(iconPath) {
    try {
        return new Uint8Array(await readFile(iconPath));
    }
    catch (error) {
        throw new CliError(`could not read --icon ${iconPath}: ${describeError(error)}`, {
            code: "invalid_argument",
            cause: error,
        });
    }
}
function renderReport(report, dryRun) {
    const lines = [
        `${dryRun ? "Would write" : "Wrote"} ${report.path}`,
        `App ID: ${report.appId}`,
        `Version: ${report.version}`,
        `Scopes: ${report.scopes.join(", ")}`,
        `Channel-post consent: ${report.channelPosts ? "yes" : "no"}`,
        ...report.notes.map((note) => `note: ${note}`),
        UPLOAD_LINE,
    ];
    return `${lines.join("\n")}\n`;
}
